-- PENDIENTE DE AUTORIZACION. No ha sido ejecutado por Codex.
-- Actualiza solo las plantillas globales originales de Informe y Oficio.
-- Conserva plantillas personalizadas: un hash desconocido detiene todo el script.
-- Ejecutar completo en idosgd_inia, despues de respaldo aprobado por el operador.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';
DO $base$
BEGIN
    IF current_database() <> 'idosgd_inia' THEN
        RAISE EXCEPTION 'Base incorrecta: %', current_database();
    END IF;
END
$base$;
LOCK TABLE idosgd.tdtr_plantilla_docx IN SHARE ROW EXCLUSIVE MODE;
CREATE TABLE IF NOT EXISTS idosgd.respaldo_plantillas_firma_20261010
    (LIKE idosgd.tdtr_plantilla_docx INCLUDING DEFAULTS);
CREATE UNIQUE INDEX IF NOT EXISTS respaldo_plantillas_firma_20261010_clave
    ON idosgd.respaldo_plantillas_firma_20261010 (co_dep,co_tipo_doc);
DO $plantillas$
DECLARE
    esperado record;
    anterior idosgd.tdtr_plantilla_docx%ROWTYPE;
    huella text;
BEGIN
    FOR esperado IN
        SELECT * FROM (VALUES
('003', 'INFORME-INIA.docx', 'b25b4e1154385d3b8b86dce582d7e806cf173d39e1d449326da5cceffca67847', '446262ac93a0a786c3ff0a9f810bbbc1b52e427f7e5fd9de5f26f61d239e0fd7', decode('','hex')),
('001', 'OFICIO-INIA.docx', 'a41dd3275c0ff645b4af98b03838052b9a558a385cabc7830efdaa126b99aedf', 'cc60481629822ac5d11fb8b9bf0d31a9a0f8d8575e7c4ee8a17b6e21477d98c0', decode('','hex'))
        ) AS p(tipo,archivo,hash_anterior,hash_nuevo,contenido)
    LOOP
        SELECT * INTO STRICT anterior FROM idosgd.tdtr_plantilla_docx
            WHERE co_dep='00000' AND co_tipo_doc=esperado.tipo;
        huella := encode(sha256(anterior.bl_doc),'hex');
        IF anterior.es_doc <> '1' OR huella IS NULL OR
            huella NOT IN (esperado.hash_anterior,esperado.hash_nuevo) THEN
            RAISE EXCEPTION 'Plantilla % distinta o inactiva: revisar antes de actualizar', esperado.tipo;
        END IF;
        IF encode(sha256(esperado.contenido),'hex') <> esperado.hash_nuevo THEN
            RAISE EXCEPTION 'Contenido del script alterado: %', esperado.tipo;
        END IF;
        IF huella = esperado.hash_anterior THEN
            INSERT INTO idosgd.respaldo_plantillas_firma_20261010
                SELECT * FROM idosgd.tdtr_plantilla_docx
                    WHERE co_dep='00000' AND co_tipo_doc=esperado.tipo
                ON CONFLICT (co_dep,co_tipo_doc) DO NOTHING;
            UPDATE idosgd.tdtr_plantilla_docx
                SET bl_doc=esperado.contenido,nom_archivo=esperado.archivo,
                    fe_modi=current_timestamp,us_modi=left(current_user,20)
                WHERE co_dep='00000' AND co_tipo_doc=esperado.tipo;
        END IF;
    END LOOP;
END
$plantillas$;
COMMIT;
